// Package aws holds the concrete device type implementation for an AWS
// account/region context ("aws_account"). Generated by
// pleiades forge new-device (internal/inventory/devicescaffold), then
// hand-completed the way internal/inventory/devices/catalyst was: this is
// not hardware, it is the addressable target cloud.aws.* methods act
// against, the same role a Catalyst Center controller plays for
// net.catalyst.*.
//
// This package's init registers NewAccount into the shared
// record.Types registry under "aws_account". internal/inventory/factory.go's
// NewItemFactory draws its batteries-included set from that registry
// rather than importing this package by name (internal/inventory/builtins.go
// blank-imports it purely to trigger this init, alongside cisco, linux,
// windows and catalyst). This package itself never imports
// internal/inventory, only the leaf internal/inventory/record package plus
// pkg/inventory, pkg/capability, and pkg/policy, so internal/inventory can
// depend on it (via that blank import) without a cycle back.
//
// Because this package lives under internal/, it is reachable only from
// code inside this module or a fork of it: Go's internal/ visibility rule
// blocks any other module from importing it at all. This generator is
// repo-contributor tooling, not end-user extensibility; a third-party
// device type arriving from outside this binary needs a separate,
// not-yet-built distribution mechanism, not this one.
package aws

import (
	"github.com/Subject-Void-LLC/the-pleiades/internal/inventory/record"
	"github.com/Subject-Void-LLC/the-pleiades/pkg/capability"
	"github.com/Subject-Void-LLC/the-pleiades/pkg/inventory"
	"github.com/Subject-Void-LLC/the-pleiades/pkg/policy"
)

func init() {
	record.RegisterType("aws_account", NewAccount)
}

// Account implements inventory.InventoryItem plus, structurally,
// capability.AWSAPICapable.
type Account struct {
	*record.Base
}

var _ inventory.InventoryItem = (*Account)(nil)

// NewAccount builds a Account from rec. It matches the
// record.Constructor shape (func(record.Record) (inventory.InventoryItem,
// error)) record.RegisterType expects.
//
// The capability set is the vendor baseline (AWSAPICapable) unioned with
// rec.Capabilities, per Phase 32's capability granularity decision:
// classification-derived data can only add to what this type already
// asserts about itself, never replace it.
func NewAccount(rec record.Record) (inventory.InventoryItem, error) {
	caps := policy.UnionSlices(
		[]capability.Name{
			capability.NameAWSAPI,
		},
		rec.Capabilities,
	)
	base := record.NewBase(rec, caps)
	return &Account{Base: base}, nil
}

// HasCapability checks the declared classification AND the structural
// registry assertion, so a true result is a guarantee, not a hope.
func (a *Account) HasCapability(name capability.Name) bool {
	return a.Declares(name) && capability.Implements(a, name)
}

// AWSRegion returns the AWS region this account context targets, the
// structural implementation of capability.AWSAPICapable that lets
// HasCapability(NameAWSAPI) return true.
//
// There is no fallback default the way Server.SSHPort falls back to 22:
// a region is not a convention, it is a real fact about where an EC2
// instance or S3 bucket lives, and guessing one wrong would create
// resources in the wrong place silently. clientForAccount refuses to
// build a client when this is empty rather than picking one.
func (a *Account) AWSRegion() string {
	region, _ := a.Properties().String("region")
	return region
}

// AWSEndpointOverride returns a non-AWS base URL every AWS API call for
// this account should target instead, or "" for real AWS.
//
// This is deliberately a device property, not a task parameter: a task
// parameter is something a runbook author writes and a runbook file is
// committed to version control, so a stray endpoint override left in a
// checked-in task would silently keep pointing every future run at a
// fake backend (or, worse, redirect a real run to an attacker-controlled
// one). Property lives on the device, which is inventory data an
// operator controls out of band, the same trust boundary
// clientForAccount already applies to credentials by reading them from
// InjectSecrets rather than params. It exists at all only for a
// LocalStack (or similar) test double; a device representing real AWS
// simply never sets it.
func (a *Account) AWSEndpointOverride() string {
	endpoint, _ := a.Properties().String("endpoint_override")
	return endpoint
}
